-- Old pattern: text column + validation
CREATE TABLE dbo.OrdersOld (
    OrderId INT PRIMARY KEY,
    Doc NVARCHAR(MAX) CHECK (ISJSON(Doc) = 1)
);

-- Modern pattern: native json type (SQL Server 2025 / Azure SQL / Fabric)
CREATE TABLE dbo.Orders (
    OrderId INT PRIMARY KEY,
    Doc JSON NOT NULL
);

SELECT JSON_OBJECT(
    'id': p.ProductId,
    'name': p.Name,
    'tags': JSON_QUERY('["sql","ai"]')
) AS ProductJson
FROM Production.Product AS p;
